const initSqlJs = require('sql.js');
const fs = require('fs');
async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // User details
  const user = db.exec(\"SELECT * FROM users WHERE email='maya.chen@example.com'\");
  console.log('=== USER ===');
  console.log('Columns:', JSON.stringify(user[0].columns));
  console.log('Data:', JSON.stringify(user[0].values[0], null, 2));

  // Check orders for this user
  const orders = db.exec(\"SELECT * FROM orders WHERE user_id='user_d3d5d0c8'\");
  if (orders.length > 0) {
    console.log('\n=== ORDERS ===');
    console.log('Columns:', JSON.stringify(orders[0].columns));
    orders[0].values.forEach((o, i) => console.log('Order ' + i + ':', JSON.stringify(o)));
  } else {
    console.log('\nNo orders found.');
  }

  // Check cart
  const cart = db.exec(\"SELECT * FROM carts WHERE user_id='user_d3d5d0c8'\");
  if (cart.length > 0) {
    console.log('\n=== CART ===');
    console.log('Columns:', JSON.stringify(cart[0].columns));
    cart[0].values.forEach((c, i) => console.log('Cart ' + i + ':', JSON.stringify(c)));
  }

  const cartItems = db.exec(\"SELECT ci.* FROM cart_items ci JOIN carts c ON ci.cart_id = c.cart_id WHERE c.user_id='user_d3d5d0c8'\");
  if (cartItems.length > 0) {
    console.log('\n=== CART ITEMS ===');
    console.log('Columns:', JSON.stringify(cartItems[0].columns));
    cartItems[0].values.forEach((c, i) => console.log('Item ' + i + ':', JSON.stringify(c)));
  }

  // All active promos again for completeness
  const promos = db.exec(\"SELECT * FROM promotions WHERE active=1\");
  console.log('\n=== ACTIVE PROMOS ===');
  console.log('Columns:', JSON.stringify(promos[0].columns));
  promos[0].values.forEach((p, i) => console.log('Promo ' + i + ':', JSON.stringify(p)));
}
main();
"

